(() => {
'use strict';
const API = '/api/v1';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const statuses = {draft:'Rascunho',in_review:'Em revisão',changes_requested:'Ajustes pedidos',approved:'Aprovado',planned:'Planejado',archived:'Arquivado'};
const roles = {owner:'Proprietário',admin:'Administrador',editor:'Editor',reviewer:'Revisor',viewer:'Leitor'};
const platformLabels = {instagram:'Instagram',facebook:'Facebook',linkedin:'LinkedIn',tiktok:'TikTok',youtube:'YouTube',pinterest:'Pinterest'};
const paths = {home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',edit:'M12 20H3v-9M15 3l6 6M8 16l-1 5 5-1L22 10 16 4z',media:'M3 3h18v18H3zM3 16l5-5 5 5 3-3 5 5M15 7h.01',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7.87a4 4 0 0 1 0 7.75',chart:'M4 20h17M7 15v-4m5 4V4m5 11V7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 2h4l1 3 3 1 3 2-1 4 1 4-3 2-3 1-1 3h-4l-1-3-3-1-3-2 1-4-1-4 3-2 3-1z',layers:'M12 3 2 8l10 5 10-5-10-5M2 12l10 5 10-5M2 16l10 5 10-5',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',logout:'M9 3H3v18h6m6-14 5 5-5 5m-7-5h12',menu:'M3 6h18M3 12h18M3 18h18',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',mail:'M3 5h18v14H3zM3 5l9 8 9-8',folder:'M3 5h7l2 3h9v12H3z',copy:'M8 8h13v13H8zM16 8V3H3v13h5',chevron:'m9 5 7 7-7 7',review:'M9 11l3 3 8-9M20 12v8H4V4h11'};
const icon = name => `<svg class="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.layers}"/></svg>`;
const mark = () => '<span class="brand-mark" aria-hidden="true">a<span>•</span></span>';
const wordmark = (subtitle = false) => `<a class="wordmark" href="#/">${mark()}<span>AgendePost${subtitle ? '<small>PILOTO CONTROLADO</small>' : ''}</span></a>`;
const badge = s => `<span class="status ${Object.hasOwn(statuses,s) ? s : 'draft'}">${esc(statuses[s] || s)}</span>`;
const initials = name => (name || '?').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const fmt = (value, options = {}) => { if (!value) return 'Sem data'; const d = new Date(value); return Number.isNaN(d.getTime()) ? 'Data inválida' : new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',...options}).format(d); };
const bytes = n => Number(n || 0) >= 1024*1024 ? `${(Number(n)/1024/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})} MiB` : `${Math.ceil(Number(n || 0)/1024)} KiB`;
const busy = () => '<div class="loading" role="status"><span class="spinner" aria-hidden="true"></span><p>Carregando dados da organização…</p></div>';
const empty = (title, body, action = '', symbol = 'layers') => `<div class="empty"><span class="empty-symbol">${icon(symbol)}</span><h3>${esc(title)}</h3><p>${esc(body)}</p>${action}</div>`;
const title = (name, description, action = '', eyebrow = 'SEU ESPAÇO EDITORIAL') => `<div class="page-title"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(name)}</h1><p>${esc(description)}</p></div>${action}</div>`;
const newPostLink = () => canWrite() && state.workspace ? '<a class="btn primary" href="#/app/editor/new">'+icon('plus')+'Criar conteúdo</a>' : '';
const localEmailNotice = '<div class="notice warn"><strong>Piloto local: nenhum email externo é enviado.</strong><br>O link fica na caixa de saída de desenvolvimento. Peça ao operador para consultar o terminal com <span class="inline-value">npm run dev:mail -- --email seu@email.com</span> e abrir o link neste navegador.</div>';
const state = {session:null,csrf:'',tenants:[],tenant:null,workspaces:[],workspace:null,page:'dashboard',plans:[],post:null,editor:null,media:[],channels:[],revision:0,dirty:false,renderId:0,month:new Date(new Date().getFullYear(),new Date().getMonth(),1),posts:[],nextCursor:null,filters:{status:'',search:''},token:null,tokenPurpose:null,invitePending:false};
const hostedPilot=()=>state.session?.capabilities?.hostedPilot===true;
const emailNotice=()=>hostedPilot()?'<div class="notice"><strong>Acesso por convite do operador.</strong><br>Contas e recuperação de senha dependem de verificação privada pelo responsável. Não há cadastro aberto ou envio automático de email.</div>':localEmailNotice;
let toastTimer;
const publishing = window.createPublishingUI({state,api,$,$$,esc,attr,icon,title,empty,brandRequired,workspacePath,safePath,canWrite,canManage,openDialog,closeDialog,confirmDialog,submitForm,toast,showError,fmt,navigate});
const pendingMutations=new Map();
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),4500);}
function showError(error, target){const e=target ? (typeof target==='string' ? $(target): target) : null;const text=error?.message || 'Não foi possível concluir. Tente novamente.';if(e){e.textContent=text;if(error?.requestId){e.append(document.createTextNode(` Referência: ${error.requestId}`));}e.scrollIntoView?.({block:'nearest'});}else toast(text);}
function safePath(id){return encodeURIComponent(id);}
function tenantPath(suffix=''){return `/tenants/${safePath(state.tenant.id)}${suffix}`;}
function workspacePath(suffix=''){return tenantPath(`/workspaces/${safePath(state.workspace.id)}${suffix}`);}
function canWrite(){return ['owner','admin','editor'].includes(state.tenant?.role);}
function canReview(){return ['owner','admin','reviewer'].includes(state.tenant?.role);}
function canManage(){return ['owner','admin'].includes(state.tenant?.role);}
function canComment(){return canWrite() || canReview();}
function hasUnsaved(){return state.dirty || Boolean(window.SocialStrategy?.isDirty()) || Boolean(window.ClientApprovals?.isDirty?.());}
function discardLocalChanges(){state.dirty=false;window.SocialStrategy?.cleanup();window.SocialResults?.cleanup();window.ClientApprovals?.cleanup?.();}
function isPlatformAdmin(){return state.session?.capabilities?.platformAdmin === true;}
function idempotency(){return crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;}
async function api(path,{method='GET',body,headers={},idempotent=false,signal}={}){
 const options={method,signal,credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json',...headers}};
 if(method!=='GET' && method!=='HEAD') options.headers['X-CSRF-Token']=state.csrf;
 if(body!==undefined){if(body instanceof FormData) options.body=body;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);}}
 let mutationIdentity;
 if(idempotent){mutationIdentity=method+':'+path+':'+(body instanceof FormData?[...body.entries()].map(([k,v])=>k+':'+(typeof v==='string'?v:[v.name,v.size,v.lastModified].join(':'))).join('|'):JSON.stringify(body));if(!pendingMutations.has(mutationIdentity))pendingMutations.set(mutationIdentity,idempotency());options.headers['Idempotency-Key']=typeof idempotent==='string'?idempotent:pendingMutations.get(mutationIdentity);}
 let response;try{response=await fetch(API+path,options);}catch(error){if(error?.name==='AbortError')throw error;throw new Error('Não foi possível acessar o servidor. Verifique sua conexão e tente novamente.');}
 if(mutationIdentity && response.status<500)pendingMutations.delete(mutationIdentity);
 const result=await response.json().catch(()=>({error:{message:'O servidor retornou uma resposta inesperada.'}}));
 if(!response.ok){const error=new Error(result.error?.message || `Solicitação não concluída (${response.status}).`);error.code=result.error?.code;error.status=response.status;error.fields=result.error?.fields;error.requestId=result.requestId;if(response.status===401 && state.session?.user){state.session.user=null;state.tenant=null;state.workspace=null;state.tenants=[];state.workspaces=[];state.media=[];state.posts=[];if(state.dirty){toast('Sessão encerrada. Seu texto permanece somente nesta aba até você sair da página.');}else{navigate('/login');}}throw error;}
 return result;
}
async function refreshSession(renderId){const result=await api('/auth/session');if(renderId!==undefined&&state.renderId!==renderId)return result.data;state.session=result.data;state.csrf=result.data.csrfToken;state.tenants=result.data.tenants || [];return result.data;}
function captureLinkToken(){const raw=location.hash.slice(1);const match=raw.match(/^\/?(verify|reset|invitation)\?(.+)$/);if(match){const params=new URLSearchParams(match[2]);state.token=params.get('token');state.tokenPurpose=match[1];history.replaceState(null,'',location.pathname+location.search+'#/'+match[1]);}}
captureLinkToken();
function routeName(){return (location.hash.slice(1) || (location.pathname.startsWith('/app')?'/app/dashboard':'/')).replace(/^([^/])/,'/$1');}
function navigate(route,replace=false){if(replace){history.replaceState(null,'',`#${route}`);routeApp();}else if(location.hash===`#${route}`){routeApp();}else location.hash=route;}
function sessionClear(){publishing.reset();window.SocialStrategy?.cleanup();window.SocialResults?.cleanup();window.ClientApprovals?.cleanup?.();pendingMutations.clear();state.tenant=null;state.workspace=null;state.tenants=[];state.workspaces=[];state.posts=[];state.media=[];state.channels=[];state.post=null;state.editor=null;state.dirty=false;state.connectionReturnRoute=null;}
function formError(form,error){const target=$('.form-error',form);showError(error,target);if(error?.code==='REAUTH_REQUIRED'&&target){const button=document.createElement('button');button.type='button';button.className='btn small section-gap';button.dataset.action='reauthenticate';button.textContent='Confirmar identidade e tentar novamente';target.append(document.createElement('br'),button);}}
async function submitForm(form,handler){if(!form.reportValidity())return;const buttons=$$('button[type="submit"]',form);buttons.forEach(b=>b.disabled=true);$('.form-error',form)?.replaceChildren();try{await handler(new FormData(form));}catch(error){formError(form,error);}finally{buttons.forEach(b=>b.disabled=false);}}
function openDialog(html){const dialog=$('#dialog');dialog.innerHTML=html;if(!dialog.open){if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}setTimeout(()=>$('input,select,textarea,button',dialog)?.focus(),0);}
function closeDialog(){const dialog=$('#dialog');if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');dialog.innerHTML='';}
function errorPage(error){return `<div class="forbidden"><span class="empty-symbol">${icon('shield')}</span><h2>${error.status===403?'Acesso não permitido':error.status===404?'Conteúdo indisponível':'Não foi possível carregar'}</h2><p>${esc(error.message)}</p>${error.requestId?`<p class="help">Referência: ${esc(error.requestId)}</p>`:''}<button class="btn" data-action="reload">Tentar novamente</button></div>`;}
function planCards(plans){if(!plans.length)return empty('Catálogo indisponível','Não foi possível obter os limites do servidor. Recarregue para tentar novamente.');return `<div class="plan-grid">${plans.map(p=>`<article class="plan-card"><span class="tag neutral">Preset técnico · versão ${esc(p.version)}</span><h3>${esc(p.label)}</h3><div class="plan-price">Preços a definir<small>Sem contratação ou cobrança neste piloto</small></div><ul><li>${esc(p.limits.workspaces)} marcas</li><li>${esc(p.limits.members)} membros, incluindo convites válidos</li><li>${esc(p.limits.posts)} conteúdos não arquivados</li><li>${esc(bytes(p.limits.mediaBytes))} de imagens normalizadas</li></ul><span class="pill">Planejamento e colaboração editorial</span></article>`).join('')}</div>`;}
async function landing(renderId){$('#app').innerHTML=`<div class="public"><nav class="site-nav" aria-label="Navegação principal">${wordmark(true)}<div class="site-links"><a class="hide-mobile" href="#/features">O que já funciona</a><a class="hide-mobile" href="#/plans">Planos</a><a class="btn" href="${state.session?.user?'#/app/dashboard':'#/login'}">${state.session?.user?'Abrir espaço':'Entrar'}</a></div></nav><main id="main"><section class="site-hero"><div><span class="tag">Piloto em desenvolvimento</span><h1>Seu conteúdo.<br>Sua equipe.<br><span>Na mesma página.</span></h1><p>Um espaço para planejar marcas, criar conteúdo e revisar cada detalhe antes de dar o próximo passo.</p><div class="actions"><a class="btn primary" href="${state.session?.user?'#/app/dashboard':'#/register'}">${state.session?.user?'Abrir meu espaço':hostedPilot()?'Acesso por convite':'Criar acesso ao piloto'}${icon('arrow')}</a><a class="btn" href="#/features">Conhecer os recursos</a></div><p class="hero-note">${hostedPilot()?'Piloto controlado por convite.':'Avaliação local controlada.'} Publicação automática exige conexão real e ativação do operador.</p></div><div class="hero-visual" aria-label="Ilustração conceitual de organização editorial"><div class="preview-window"><div class="preview-top"><strong>Uma ideia de cada vez</strong><div class="preview-dots"><span></span><span></span><span></span></div></div><div class="preview-row"><div class="preview-thumb"></div><div class="preview-copy"><small>CRIAR</small><div class="preview-line"></div><div class="preview-line short"></div></div>${badge('draft')}</div><div class="preview-row"><div class="preview-thumb sage"></div><div class="preview-copy"><small>REVISAR</small><div class="preview-line"></div><div class="preview-line short"></div></div>${badge('in_review')}</div><div class="preview-line short"></div></div><div class="preview-float"><span class="check-symbol">${icon('check')}</span><span>O histórico acompanha<br>cada nova versão.</span></div><div class="visual-caption">Ilustração do fluxo editorial. Sem dados de clientes.</div></div></section><section class="site-section tint" id="features"><div class="section-inner"><div class="section-title"><div class="eyebrow">DO RASCUNHO AO PLANEJAMENTO</div><h2>Menos peças soltas.<br>Mais clareza para a equipe.</h2><p>O piloto reúne o trabalho editorial com acesso por organização e marca. Cada pessoa trabalha dentro das permissões que recebeu.</p></div><div class="features"><article class="feature"><span class="empty-symbol">${icon('calendar')}</span><h3>Planejamento por marca</h3><p>Organize conteúdos e intenções de data em um calendário. Separe a intenção editorial dos envios automáticos. Consulte a fila e a conexão real de cada canal.</p></article><article class="feature"><span class="empty-symbol">${icon('review')}</span><h3>Aprovação da versão certa</h3><p>Revise, comente e peça ajustes. A aprovação vale para uma revisão específica e é invalidada quando o conteúdo muda.</p></article><article class="feature"><span class="empty-symbol">${icon('shield')}</span><h3>Um espaço para cada cliente</h3><p>Marcas, imagens privadas e papéis de acesso separados. Convide editores, revisores e leitores para as marcas que precisam ver.</p></article></div></div></section><section class="site-section" id="plans"><div class="section-title"><div class="eyebrow">UM PRODUTO EM CONSTRUÇÃO</div><h2>Limites claros desde o começo.</h2><p>Estes presets técnicos permitem avaliar o produto. Os preços e as condições comerciais ainda serão definidos. Não há venda de assinatura aqui.</p></div><div id="public-plans">${busy()}</div></section></main><footer class="site-footer"><span>AgendePost · piloto controlado</span><span>Publicação condicionada à configuração e à autorização das contas. Cobrança desativada.</span></footer></div>`;
 try{const result=await api('/plans');if(state.renderId!==renderId)return;state.plans=result.data;$('#public-plans').innerHTML=planCards(result.data);}catch(e){if(state.renderId===renderId)$('#public-plans').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}
 if(routeName()==='/features')$('#features')?.scrollIntoView();if(routeName()==='/plans')$('#plans')?.scrollIntoView();
}
function authLayout(content){$('#app').innerHTML=`<div class="auth-shell"><aside class="auth-art">${wordmark(true)}<div class="auth-copy"><div class="eyebrow">IDEIAS MERECEM ESPAÇO</div><h2>O próximo conteúdo começa com uma equipe alinhada.</h2><p>Crie, converse e revise em um só lugar. Com histórico de versões e acesso separado por marca.</p></div><div class="auth-ring" aria-hidden="true"></div><small>Piloto em desenvolvimento. Publicação social requer ativação verificada.</small></aside><main class="auth-main" id="main"><div class="auth-card"><div class="auth-mobile-brand">${wordmark()}</div><a href="#/" class="auth-back">${icon('back')}Voltar ao início</a>${content}</div></main></div>`;}
function authPage(page){
 if(hostedPilot()&&['register','forgot'].includes(page)){authLayout(`<div class="eyebrow">PILOTO POR CONVITE</div><h1>${page==='forgot'?'Recuperar seu acesso.':'Acesso controlado.'}</h1><p>Fale com o responsável pelo AgendePost para ${page==='forgot'?'verificar sua identidade e receber um link privado de recuperação':'receber seu convite pessoal'}. Cada link expira e só pode ser usado uma vez.</p>${emailNotice()}<p class="auth-footer"><a href="#/login">Voltar para entrar</a></p>`);return;}

 if(page==='register'){authLayout(`<div class="eyebrow">COMECE SEU ESPAÇO</div><h1>Vamos organizar suas ideias?</h1><p>Cadastre seu nome e email. Você define a senha ao abrir o link de verificação local.</p><form id="register-form"><div class="field"><label for="display-name">Seu nome</label><input id="display-name" name="displayName" autocomplete="name" required minlength="2" maxlength="100"></div><div class="field"><label for="register-email">Email</label><input id="register-email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Criar acesso ao piloto${icon('arrow')}</button></form>${emailNotice()}<p class="auth-footer">Já tem acesso? <a href="#/login">Entrar</a></p>`);return;}
 if(page==='forgot'){authLayout(`<div class="eyebrow">RECUPERAR ACESSO</div><h1>Uma nova senha.</h1><p>Informe o email da conta para solicitar um link de recuperação.</p><form id="forgot-form"><div class="field"><label for="forgot-email">Email</label><input id="forgot-email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Solicitar recuperação</button></form>${emailNotice()}<p class="auth-footer"><a href="#/login">Voltar para entrar</a></p>`);return;}
 if(page==='verify' || page==='reset'){const verify=page==='verify';authLayout(`<div class="eyebrow">${verify?'VERIFIQUE SEU ACESSO':'REDEFINA SUA SENHA'}</div><h1>${verify?'Pronto para começar.':'Recupere seu espaço.'}</h1><p>${verify?'Defina uma senha para concluir a verificação da conta.':'Defina uma senha nova. As sessões anteriores serão encerradas.'}</p>${state.token && state.tokenPurpose===page?`<form id="token-form" data-purpose="${page}"><div class="field"><label for="token-password">${verify?'Sua senha':'Nova senha'}</label><input id="token-password" name="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"><small class="help">Use de 15 a 128 caracteres. Espaços são permitidos.</small></div><div class="field"><label for="token-confirm">Repita a senha</label><input id="token-confirm" name="confirm" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">${verify?'Verificar conta':'Redefinir senha'}</button></form>`:`<div class="notice warn">Este link não tem um token disponível. Ele é removido do endereço por segurança. Se você recarregou esta página, abra novamente o link original do terminal.</div>`}${verify&&!hostedPilot()?`<div class="rule"></div><form id="resend-form"><div class="field"><label for="resend-email">Solicitar um novo link de verificação</label><input id="resend-email" name="email" type="email" autocomplete="email" required placeholder="seu@email.com"></div><div class="form-error" role="alert"></div><button class="btn full" type="submit">Gerar novo link local</button></form>`:'<p class="auth-footer"><a href="#/forgot">Solicitar um novo link</a></p>'}${emailNotice()}`);return;}
 if(page==='invitation'){authLayout(`<div class="eyebrow">TRABALHE EM EQUIPE</div><h1>Você recebeu um convite.</h1><p>Para aceitar, entre com a conta verificada do mesmo email que recebeu o convite.</p>${!state.token?'<div class="notice warn">Reabra o link original do convite para continuar. O token já foi removido do endereço.</div>':state.session?.user?`<div class="notice">Conectado como <strong>${esc(state.session.user.email)}</strong>.</div><form id="accept-invite-form"><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Aceitar convite</button></form><p class="auth-footer"><button class="btn text" data-action="logout">Entrar com outra conta</button></p>`:`<div class="notice">O convite ficará somente na memória desta aba enquanto você entra.</div><a class="btn primary full" href="#/login" data-invite-login="true">Entrar para aceitar</a><p class="auth-footer">Ainda não tem conta? <a href="#/register">Criar acesso verificado</a></p>`}`);return;}
 authLayout(`<div class="eyebrow">SEU ESPAÇO ESTÁ AQUI</div><h1>Que bom ter você por perto.</h1><p>Entre para continuar o planejamento com sua equipe.</p><form id="login-form"><div class="field"><label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="username" required maxlength="254"></div><div class="field"><div class="row"><label for="login-password">Senha</label><a class="help" href="#/forgot">Esqueci minha senha</a></div><input id="login-password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div><div class="form-error" role="alert"></div><button class="btn primary full" type="submit">Entrar${icon('arrow')}</button></form><p class="auth-footer">Primeira vez aqui? <a href="#/register">${hostedPilot()?'Como receber acesso':'Criar acesso ao piloto'}</a></p><p class="email-note">${hostedPilot()?'Acesso somente a pessoas convidadas pelo operador.':'Contas de desenvolvimento verificadas por link local.'} Nenhum email externo é enviado neste piloto.</p>`);
}
async function loadTenants(){const result=await api('/me/tenants');state.tenants=result.data;return result.data;}
async function loadTenantContext(renderId=state.renderId){const chosen=state.tenants.find(t=>t.id===state.tenant?.id)||state.tenants[0];if(!chosen){if(state.renderId===renderId)state.tenant=null;return;}const wantedWorkspace=state.workspace?.id;const result=await api(`/tenants/${safePath(chosen.id)}`);if(state.renderId!==renderId)return;const brands=await api(`/tenants/${safePath(chosen.id)}/workspaces?limit=100&archived=all`);if(state.renderId!==renderId)return;state.tenant={...chosen,...result.data};state.workspaces=brands.data;state.workspace=state.workspaces.find(w=>w.id===wantedWorkspace&&!w.archivedAt)||state.workspaces.find(w=>!w.archivedAt)||null;state.workspaceCursor=brands.meta?.nextCursor;}
function shell(){const page=state.page;const nav=[['dashboard','Visão geral','home'],['calendar','Calendário','calendar'],['publishing','Agendamentos','clock'],['posts','Conteúdos','edit'],['media','Biblioteca','media'],['results','Dashboard do cliente','chart'],['approvals','Aprovações','review'],['reports','Estratégia editorial','chart']];const second=[['brands','Marcas e canais','layers'],['connections','Conexões sociais','shield'],...(canManage()?[['team','Equipe e acesso','team']]:[]),['plans','Plano e uso','layers'],['settings','Configurações','settings'],...(isPlatformAdmin()?[['admin','Operação da plataforma','shield']]:[])];$('#app').innerHTML=`<div class="app-shell"><div class="mobile-overlay" data-action="menu-close"></div><aside class="sidebar" aria-label="Navegação do espaço">${wordmark()}<div class="tenant-control"><label for="tenant-select">Organização</label><select id="tenant-select" aria-label="Organização">${state.tenants.map(t=>`<option value="${attr(t.id)}" ${t.id===state.tenant?.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="nav-caption">PLANEJAMENTO</div><nav>${nav.map(([key,label,symbol])=>`<a class="nav-item ${page===key || page==='editor'&&key==='posts'?'active':''}" href="#/app/${key}" ${page===key?'aria-current="page"':''}>${icon(symbol)}${label}</a>`).join('')}</nav><div class="nav-caption">SEU ESPAÇO</div><nav>${second.map(([key,label,symbol])=>`<a class="nav-item ${page===key?'active':''}" href="#/app/${key}" ${page===key?'aria-current="page"':''}>${icon(symbol)}${label}</a>`).join('')}</nav><div class="side-bottom"><span class="pilot-tag">PILOTO EM DESENVOLVIMENTO</span><p>Planejamento e publicação.<br>Ativação social depende do operador.</p><div class="side-user"><span class="avatar">${esc(initials(state.session.user.displayName))}</span><span><strong>${esc(state.session.user.displayName)}</strong><small>${esc(roles[state.tenant?.role] || 'Conta verificada')}</small></span></div></div></aside><div class="app-body"><header class="topbar"><div class="breadcrumb"><button class="btn icon mobile-menu" data-action="menu" aria-label="Abrir navegação">${icon('menu')}</button><span>Seu espaço</span><span>/</span><strong>${esc(state.tenant?.name || 'Nova organização')}</strong></div><div class="top-right">${state.tenant?`<select id="brand-select" class="brand-select" aria-label="Marca ativa">${state.workspaces.filter(w=>!w.archivedAt).map(w=>`<option value="${attr(w.id)}" ${w.id===state.workspace?.id?'selected':''}>${esc(w.name)}</option>`).join('') || '<option value="">Nenhuma marca</option>'}</select>`:''}<span class="pilot-text">AMBIENTE DE AVALIAÇÃO</span><button class="btn icon" data-action="logout" aria-label="Sair da conta" title="Sair">${icon('logout')}</button></div></header><main id="main" class="main">${busy()}</main></div></div>`;}
function onboarding(){shell();$('#main').innerHTML=`<section class="onboard"><div class="eyebrow">SEU PRIMEIRO ESPAÇO</div><h1>Uma casa para suas marcas.</h1><p>Crie sua organização. Ela começa vazia, pronta para receber sua equipe e seus conteúdos.</p><form id="tenant-form"><div class="field"><label for="tenant-name">Nome da organização</label><input id="tenant-name" name="name" required maxlength="100" placeholder="Sua agência ou empresa"></div><div class="field"><label for="tenant-timezone">Fuso horário</label><input id="tenant-timezone" name="timezone" required value="America/Sao_Paulo" maxlength="100"><small class="help">Use um fuso IANA, como America/Sao_Paulo ou Europe/Lisbon.</small></div><div class="notice">A revisão independente vem ativada: uma pessoa diferente da autora da versão precisa aprovar.</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Criar organização${icon('arrow')}</button></form></section>`;}
function brandRequired(){return empty('Vamos começar por uma marca?','Cada marca tem seus próprios conteúdos, canais editoriais e imagens privadas.',canManage()?'<button class="btn primary" data-action="brand-new">'+icon('plus')+'Criar primeira marca</button>':'<p>Peça a um administrador para conceder acesso a uma marca.</p>','layers');}
function postRow(p){const media=p.media?.[0];const d=p.scheduledAt?new Date(p.scheduledAt):null;return `<article class="post-row">${d?`<div class="date-box"><strong>${esc(new Intl.DateTimeFormat('pt-BR',{day:'2-digit',timeZone:state.tenant.timezone}).format(d))}</strong>${esc(new Intl.DateTimeFormat('pt-BR',{month:'short',timeZone:state.tenant.timezone}).format(d).replace('.',''))}</div>`:'<div class="date-box">Sem<br>data</div>'}${media?`<img class="post-thumb" src="${attr(media.contentUrl || workspacePath('/media/'+safePath(media.id)+'/content').replace(/^/ ,API))}" alt="" loading="lazy">`:`<span class="post-thumb">${icon('edit')}</span>`}<div class="post-summary"><a href="#/app/editor/${attr(p.id)}">${esc(p.title)}</a><small>${esc((p.channels || []).map(c=>c.label).join(' · ') || 'Sem alvo editorial')} · revisão ${esc(p.revision)}</small></div>${badge(p.status)}</article>`;}
async function dashboard(renderId){const reports=await api(tenantPath('/reports/editorial'));const postResult=state.workspace?await api(workspacePath('/posts?limit=6')):{data:[]};if(state.renderId!==renderId)return;const r=reports.data,c=r.counts;$('#main').innerHTML=title('Tudo encontra seu lugar.','Um olhar sobre o planejamento da sua equipe.',newPostLink(),'VISÃO GERAL')+`<section class="welcome"><div><div class="eyebrow">${esc(state.workspace?.name || state.tenant.name)}</div><h2>Da primeira ideia ao conteúdo aprovado.</h2><p>Planeje com contexto, compartilhe comentários e acompanhe cada versão. Sua próxima boa ideia pode começar aqui.</p>${newPostLink() || '<a class="btn soft" href="#/app/brands">Ver marcas disponíveis</a>'}</div><div class="welcome-art" aria-hidden="true"></div></section><div class="metrics">${[['Conteúdos no espaço',r.totalPosts,'layers'],['Aguardando revisão',c.in_review,'review'],['Aprovados',c.approved,'check'],['Planejados',c.planned,'calendar']].map(([label,value,symbol])=>`<article class="metric"><div class="metric-label">${label}${icon(symbol)}</div><strong>${esc(value)}</strong><small>Nas marcas às quais você tem acesso</small></article>`).join('')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>Conteúdos da marca</h2><p>${esc(state.workspace?.name || 'Nenhuma marca selecionada')}</p></div><a class="btn text" href="#/app/posts">Ver conteúdos${icon('arrow')}</a></div>${postResult.data.length?postResult.data.map(postRow).join(''):state.workspace?empty('Uma página em branco.','Comece com um rascunho. O planejamento toma forma um conteúdo de cada vez.',newPostLink(),'edit'):brandRequired()}</section><section class="panel"><div class="panel-head"><div><h2>O caminho das ideias</h2><p>Distribuição editorial do seu escopo</p></div></div><div class="panel-body"><div class="pipeline">${Object.entries(statuses).filter(([s])=>s!=='archived').map(([s,label])=>`<div class="pipeline-item"><div class="row"><span>${label}</span><strong>${esc(c[s] || 0)}</strong></div><div class="meter"><span data-progress="${Math.round((c[s]||0)/Math.max(1,r.totalPosts)*100)}"></span></div></div>`).join('')}</div><div class="notice">Planejado significa intenção editorial. Para enviar automaticamente, use Agendar publicação no conteúdo aprovado e acompanhe a fila em Agendamentos.</div></div></section></div>`;applyProgress();}
function applyProgress(){ $$('[data-progress]').forEach(e=>{e.style.width=`${Math.max(0,Math.min(100,Number(e.dataset.progress)||0))}%`;}); }
async function loadPosts(append=false){const renderId=state.renderId,context=state.tenant.id+':'+state.workspace.id;const query=new URLSearchParams({limit:'50'});if(state.filters.status)query.set('status',state.filters.status);if(append && state.nextCursor)query.set('cursor',state.nextCursor);const result=await api(workspacePath('/posts?'+query));if(state.renderId!==renderId||context!==state.tenant?.id+':'+state.workspace?.id)return {ignored:true};state.posts=append?[...state.posts,...result.data]:result.data;state.nextCursor=result.meta?.nextCursor;return result;}
function postListBody(){const search=state.filters.search.toLocaleLowerCase('pt-BR');const posts=state.posts.filter(p=>(p.title+' '+p.caption).toLocaleLowerCase('pt-BR').includes(search));return posts.length?posts.map(postRow).join(''):empty('Nenhum conteúdo por aqui.',state.filters.status || search?'Experimente mudar os filtros. A busca procura apenas nos conteúdos carregados.':'Crie seu primeiro rascunho para esta marca.',newPostLink(),'edit');}
function postsMarkup(){return title('Conteúdos','Criação, revisão e planejamento em um só lugar.',newPostLink())+`<div class="toolbar"><div class="filters"><input id="post-search" type="search" aria-label="Buscar nos conteúdos carregados" placeholder="Buscar nos itens carregados" value="${attr(state.filters.search)}"><select id="post-status" aria-label="Filtrar por status"><option value="">Ativos: todos os status</option>${Object.entries(statuses).map(([s,label])=>`<option value="${s}" ${state.filters.status===s?'selected':''}>${label}</option>`).join('')}</select></div><span class="filter-note">${state.posts.length} carregado(s) · ${esc(state.workspace.name)}</span></div><section class="panel"><div id="post-list">${postListBody()}</div>${state.nextCursor?'<div class="pagination"><button class="btn" data-action="posts-more">Carregar mais conteúdos</button></div>':''}</section>`;}
async function postsPage(renderId){if(!state.workspace){$('#main').innerHTML=title('Conteúdos','Seu planejamento por marca.')+brandRequired();return;}await loadPosts();if(state.renderId===renderId)$('#main').innerHTML=postsMarkup();}
function dateKey(date,timeZone){return new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone}).format(date);}
async function calendarPage(renderId,append=false){if(!state.workspace){$('#main').innerHTML=title('Calendário','Intenções de data, sem publicação automática.')+brandRequired();return;}const m=state.month;const from=new Date(Date.UTC(m.getFullYear(),m.getMonth(),1)-86400000).toISOString();const to=new Date(Date.UTC(m.getFullYear(),m.getMonth()+1,2)).toISOString();const query=new URLSearchParams({from,to,limit:'100'});if(append&&state.calendarCursor)query.set('cursor',state.calendarCursor);const r=await api(workspacePath('/posts?'+query));if(state.renderId!==renderId)return;state.calendarPosts=append?[...state.calendarPosts,...r.data]:r.data;state.calendarCursor=r.meta?.nextCursor;const start=new Date(m.getFullYear(),m.getMonth(),1);const days=new Date(m.getFullYear(),m.getMonth()+1,0).getDate();const offset=(start.getDay()+6)%7;const today=dateKey(new Date(),state.tenant.timezone);const cells=[];for(let i=0;i<Math.ceil((days+offset)/7)*7;i++){const day=i-offset+1;const inMonth=day>0&&day<=days;const date=new Date(m.getFullYear(),m.getMonth(),day);const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const posts=state.calendarPosts.filter(p=>p.scheduledAt&&dateKey(new Date(p.scheduledAt),state.tenant.timezone)===key);cells.push(`<div class="calendar-cell ${inMonth?'':'outside'}"><span class="calendar-day ${today===key?'today':''}">${date.getDate()}</span>${posts.map(p=>`<a class="calendar-post" href="#/app/editor/${attr(p.id)}"><time>${esc(new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:state.tenant.timezone}).format(new Date(p.scheduledAt)))}</time><strong>${esc(p.title)}</strong>${esc(statuses[p.status])}</a>`).join('')}</div>`);}$('#main').innerHTML=title('Calendário','Seu planejamento ganha uma visão do todo.',newPostLink())+`<div class="toolbar"><div class="actions"><button class="btn icon" data-action="month-prev" aria-label="Mês anterior">${icon('back')}</button><h2 class="month-label">${esc(new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(m))}</h2><button class="btn icon" data-action="month-next" aria-label="Próximo mês">${icon('arrow')}</button><button class="btn small" data-action="month-now">Este mês</button></div><span class="filter-note">${esc(state.tenant.timezone)}</span></div><div class="calendar">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${cells.join('')}</div>${state.calendarCursor?'<div class="notice warn">Há mais itens neste mês. Carregue os próximos para completar o calendário. <button class="btn small" data-action="calendar-more">Carregar mais</button></div>':''}<p class="calendar-mobile-note">Toque em um conteúdo para abrir os detalhes.</p><div class="notice">O calendário mostra intenções de data no fuso da organização. Planejar não publica. Conteúdos sem data estão em <a href="#/app/posts">Conteúdos</a>.</div>`;}
const formatLabels={image:'Imagem',carousel:'Carrossel',video:'Vídeo (planejamento)',reel:'Reel (planejamento)',story:'Story (planejamento)',text:'Texto'};
function mediaUrl(m){return m.contentUrl || API+workspacePath(`/media/${safePath(m.id)}/content`);}
function editorActions(p){if(!p)return '';const controls=[];if(canWrite()&&['draft','changes_requested'].includes(p.status))controls.push('<button class="btn primary" data-transition="submit_review">'+icon('review')+'Solicitar revisão</button>');if(canReview()&&p.status==='in_review'){controls.push('<button class="btn primary" data-transition="approve">'+icon('check')+'Aprovar esta versão</button>','<button class="btn" data-transition="request_changes">Pedir ajustes</button>');}if(canWrite()&&p.status==='approved')controls.push('<button class="btn primary" data-transition="plan">'+icon('calendar')+'Planejar data</button>');if(canWrite())controls.push(p.status==='archived'?'<button class="btn" data-transition="restore">Restaurar como rascunho</button>':'<button class="btn" data-transition="archive">Arquivar</button>');return controls.join('');}
async function editorPage(renderId,pid){if(!state.workspace){$('#main').innerHTML=brandRequired();return;}const isNew=pid==='new';if(isNew&&!canWrite())throw Object.assign(new Error('Seu papel não permite criar conteúdos.'),{status:403});const [post,channels,media]=await Promise.all([isNew?Promise.resolve({data:null}):api(workspacePath('/posts/'+safePath(pid))),api(workspacePath('/channels?limit=100')),api(workspacePath('/media?limit=100'))]);if(state.renderId!==renderId)return;state.post=post.data;state.revision=post.data?.revision || 0;state.channels=channels.data;state.media=media.data;state.mediaCursor=media.meta?.nextCursor;state.selectedMedia=new Set(post.data?.mediaIds || []);state.dirty=false;state.editorBasePath=workspacePath('/posts'+(post.data?'/'+safePath(post.data.id):''));const p=post.data || {title:'',caption:'',format:'image',tags:[],channelIds:[],mediaIds:[],status:'draft'};const editable=canWrite()&&p.status!=='archived';$('#main').innerHTML=title(isNew?'Uma nova ideia.':'Cada detalhe importa.',`${state.workspace.name} · ${isNew?'Novo rascunho':`Revisão ${state.revision}`}`,`<a class="btn" href="#/app/posts">${icon('back')}Voltar</a>`,'ESTÚDIO DE CONTEÚDO')+`<div class="editor-grid"><div class="stack"><section class="panel"><div class="panel-head"><div class="actions">${badge(p.status)}${p.approvedRevision?`<span class="pill">Aprovado: revisão ${esc(p.approvedRevision)}</span>`:''}</div><span id="save-state" class="help">${isNew?'Ainda não salvo':'Salvo no servidor'}</span></div><div class="panel-body"><form id="editor-form"><div class="field"><label for="post-title">Título interno</label><input id="post-title" name="title" value="${attr(p.title)}" required maxlength="180" ${!editable?'readonly':''} placeholder="Dê um nome a esta ideia"></div><div class="field"><label for="post-caption">Legenda ou texto</label><textarea id="post-caption" name="caption" maxlength="10000" ${!editable?'readonly':''} placeholder="O que sua marca quer dizer?">${esc(p.caption)}</textarea><small class="help"><span id="caption-count">${p.caption.length}</span> / 10.000 caracteres</small></div><div class="field-row"><div class="field"><label for="post-format">Formato editorial</label><select id="post-format" name="format" ${!editable?'disabled':''}>${Object.entries(formatLabels).map(([key,label])=>`<option value="${key}" ${p.format===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="post-tags">Tags internas</label><input id="post-tags" name="tags" value="${attr((p.tags||[]).join(', '))}" ${!editable?'readonly':''} placeholder="campanha, lançamento"><small class="help">Até 20 tags, separadas por vírgula.</small></div></div><fieldset class="field"><legend>Alvos editoriais</legend><div class="channel-list">${state.channels.length?state.channels.map(c=>`<label class="channel-option"><input type="checkbox" name="channelIds" value="${attr(c.id)}" ${(p.channelIds||[]).includes(c.id)?'checked':''} ${!editable?'disabled':''}><span class="platform">${esc((platformLabels[c.platform]||c.platform).slice(0,2))}</span><span>${esc(c.label)}</span></label>`).join(''):'<p class="help">Nenhum canal editorial nesta marca. '+(canManage()?'<a href="#/app/brands">Adicionar um canal</a>.':'Peça a um administrador para adicionar.')+'</p>'}</div><small class="help">Esta seleção define os alvos editoriais. Para autorizar um envio real, use Agendar publicação após a aprovação. Verifique o acesso em Conexões sociais.</small></fieldset><div class="field"><label>Imagens da marca</label><div id="editor-media" class="media-picker">${editorMediaMarkup(editable)}</div>${state.mediaCursor?'<button type="button" class="btn small section-gap" data-action="editor-media-more">Carregar mais imagens</button>':''}<small class="help">Selecione até 10 imagens. Vídeos são apenas formatos de planejamento neste piloto. <a href="#/app/media">Gerenciar biblioteca</a>.</small></div><div id="editor-conflict"></div><div class="form-error" role="alert"></div>${editable?`<div class="actions"><button type="submit" class="btn primary">${icon('check')}${isNew?'Salvar rascunho':'Salvar nova versão'}</button><span class="help">Alterações invalidam aprovações anteriores.</span></div>`:'<div class="notice">'+(p.status==='archived'?'Restaure o conteúdo para editar.':'Seu acesso permite leitura e, conforme o papel, revisão.')+'</div>'}</form></div></section>${!isNew?`<section class="panel"><div class="panel-head"><h2>Conversa sobre este conteúdo</h2></div><div class="panel-body"><div id="comments-list">${busy()}</div>${canComment()&&p.status!=='archived'?'<form id="comment-form" class="section-gap"><div class="field"><label for="comment-body">Seu comentário</label><textarea id="comment-body" name="body" required maxlength="5000" rows="3" placeholder="Acrescente contexto para a equipe…"></textarea></div><div class="form-error" role="alert"></div><button class="btn" type="submit">Enviar comentário</button></form>':''}</div></section>`:''}</div><div class="stack"><section class="panel"><div class="panel-head"><h2>Próximo passo</h2>${icon('review')}</div><div class="panel-body">${isNew?'<p class="help">Salve o rascunho para abrir a revisão, receber comentários e construir o histórico.</p>':`<div class="stack">${editorActions(p) || '<p class="help">Nenhuma ação de revisão disponível para seu papel neste status.</p>'}</div><div class="rule"></div><div class="editor-metadata">Atualizado: ${esc(fmt(p.updatedAt,{timeStyle:'short'}))}<br>Autor da criação: ${esc(p.authorId===state.session.user.id?'você':p.authorId)}<br>Última edição: ${esc(p.updatedBy===state.session.user.id?'você':p.updatedBy)}${p.scheduledAt?`<br>Data planejada: ${esc(fmt(p.scheduledAt,{timeStyle:'short',timeZone:p.scheduledTimezone}))}<br>Fuso: ${esc(p.scheduledTimezone)}`:''}</div>${canWrite()?'<div class="rule"></div><button class="btn small" data-action="post-duplicate">'+icon('copy')+'Duplicar como rascunho</button>':''}`}<div class="notice">${state.tenant.requireIndependentApproval?'Revisão independente ativada. O autor da revisão não pode aprová-la.':'Revisão independente desativada nesta organização.'}</div></div></section>${publishing.editorPanel(p,isNew)}${!isNew?'<section class="panel"><div class="panel-head"><h2>Versões e decisões</h2></div><div class="panel-body" id="revisions-list">'+busy()+'</div></section>':''}</div></div>`;if(!isNew)await Promise.all([loadComments(false,renderId),loadRevisions(false,renderId),publishing.loadEditor(renderId)]);}
function editorMediaMarkup(editable=true){return state.media.length?state.media.map(m=>`<button type="button" class="media-choice ${state.selectedMedia.has(m.id)?'selected':''}" data-media-select="${attr(m.id)}" aria-label="${attr(m.originalName)}" aria-pressed="${state.selectedMedia.has(m.id)}" ${!editable?'disabled':''}><img src="${attr(mediaUrl(m))}" alt="${attr(m.originalName)}" loading="lazy">${state.selectedMedia.has(m.id)?'<span>✓</span>':''}</button>`).join(''):'<p class="help">Sua biblioteca está vazia.</p>';}
async function loadComments(append=false,renderId=state.renderId){const path=state.editorBasePath+'/comments?limit=30'+(append&&state.commentCursor?'&cursor='+encodeURIComponent(state.commentCursor):'');const r=await api(path);if(state.renderId!==renderId)return;state.comments=append?[...state.comments,...r.data]:r.data;state.commentCursor=r.meta?.nextCursor;$('#comments-list').innerHTML=state.comments.map(c=>`<article class="comment"><div class="comment-head"><span class="avatar">${c.authorId===state.session.user.id?esc(initials(state.session.user.displayName)):'·'}</span><strong>${esc(c.authorId===state.session.user.id?state.session.user.displayName:'Membro '+c.authorId.slice(0,8))}</strong><time>${esc(fmt(c.createdAt,{timeStyle:'short'}))}</time></div><p>${esc(c.body)}</p></article>`).join('') || '<p class="help">Ainda não há comentários. A conversa começa aqui.</p>';if(state.commentCursor)$('#comments-list').insertAdjacentHTML('beforeend','<button class="btn small section-gap" data-action="comments-more">Carregar mais comentários</button>');}
async function loadRevisions(append=false,renderId=state.renderId){const r=await api(state.editorBasePath+'/revisions?limit=20'+(append&&state.revisionCursor?'&cursor='+encodeURIComponent(state.revisionCursor):''));if(state.renderId!==renderId)return;state.revisions=append?[...state.revisions,...r.data]:r.data;state.revisionCursor=r.meta?.nextCursor;$('#revisions-list').innerHTML=[...state.revisions].reverse().map(v=>`<article class="history-item"><div class="row"><strong>Revisão ${esc(v.revision)}</strong><small>${esc(fmt(v.createdAt))}</small></div><p>${esc(v.content.title)}</p>${v.approvals.map(a=>`<div class="notice ${a.decision==='approved'||a.decision==='approve'?'success':'warn'}">${esc(a.decision==='approved'||a.decision==='approve'?'Aprovada':'Ajustes solicitados')} nesta versão por ${esc(a.reviewerId===state.session.user.id?'você':'membro '+a.reviewerId.slice(0,8))}.${a.reason?'<br>'+esc(a.reason):''}</div>`).join('')}<details><summary>Ver texto desta versão</summary><p>${esc(v.content.caption || 'Sem legenda.')}</p><p class="help">${esc((v.content.mediaIds||[]).length)} imagem(ns) · ${esc((v.content.channelIds||[]).length)} alvo(s)</p></details></article>`).join('');if(state.revisionCursor)$('#revisions-list').insertAdjacentHTML('beforeend','<button class="btn small section-gap" data-action="revisions-more">Carregar mais versões</button>');}
function markDirty(){state.dirty=true;publishing.markDirty();const e=$('#save-state');if(e)e.textContent='Alterações ainda não salvas';}
function collectPost(form){const f=new FormData(form);const tags=[...new Set(String(f.get('tags')||'').split(',').map(t=>t.trim()).filter(Boolean))];if(tags.length>20)throw new Error('Use no máximo 20 tags internas.');if(tags.some(t=>t.length>60))throw new Error('Cada tag pode ter até 60 caracteres.');return {title:String(f.get('title')).trim(),caption:String(f.get('caption')||''),format:String(f.get('format')),tags,channelIds:f.getAll('channelIds'),mediaIds:[...state.selectedMedia]};}
async function savePost(form){const renderId=state.renderId,basePath=state.editorBasePath,existing=!!state.post;await submitForm(form,async()=>{const body=collectPost(form);if(state.post)body.expectedRevision=state.revision;try{const result=await api(basePath,{method:existing?'PATCH':'POST',body,idempotent:true});if(state.renderId!==renderId)return;state.dirty=false;toast(existing?'Nova versão salva.':'Rascunho criado.');navigate('/app/editor/'+result.data.id,true);}catch(e){if(e.status===409 && state.renderId===renderId){$('#editor-conflict').innerHTML='<div class="notice warn"><strong>Não sobrescrevemos sua edição.</strong><br>O servidor recusou a alteração. Seu texto continua neste formulário. Se outra pessoa editou a peça, copie suas mudanças antes de carregar a versão atual.<br><button type="button" class="btn small section-gap" data-action="post-reload">Recarregar versão do servidor</button></div>';}throw e;}});}
function offsetForZone(zone){try{const name=new Intl.DateTimeFormat('en',{timeZone:zone,timeZoneName:'longOffset'}).formatToParts(new Date()).find(p=>p.type==='timeZoneName').value;return name==='GMT'?'+00:00':name.replace('GMT','');}catch{return '-03:00';}}
function transitionDialog(action){if(state.dirty){toast('Salve suas alterações antes de mudar o status.');return;}const labels={submit_review:'Solicitar revisão',approve:'Aprovar esta versão',request_changes:'Pedir ajustes',plan:'Planejar data',archive:'Arquivar conteúdo',restore:'Restaurar como rascunho'};const planning=action==='plan';openDialog(`<h2 id="dialog-title">${labels[action]}</h2><p>Ação sobre a revisão ${state.revision} de “${esc(state.post.title)}”. ${action==='approve'?'A aprovação valerá somente para esta versão.':''}${action==='archive'?'O conteúdo sai das listas ativas e pode ser restaurado.':''}</p><form id="transition-form" data-transition-action="${action}">${planning?`<div class="field"><label for="plan-date">Data e hora local</label><input id="plan-date" name="date" type="datetime-local" required></div><div class="field-row"><div class="field"><label for="plan-zone">Fuso IANA</label><input id="plan-zone" name="scheduledTimezone" value="${attr(state.tenant.timezone)}" required maxlength="100"></div><div class="field"><label for="plan-offset">Offset dessa data</label><input id="plan-offset" name="offset" value="${attr(offsetForZone(state.tenant.timezone))}" required pattern="[+-][0-9]{2}:[0-9]{2}" placeholder="-03:00"></div></div><div class="notice">O servidor confere o offset com o fuso escolhido, inclusive em mudanças de horário de verão. A data é uma intenção editorial; nenhum envio será feito.</div>`:''}<div class="field"><label for="transition-reason">${action==='request_changes'?'Quais ajustes são necessários?':'Observação (opcional)'}</label><textarea id="transition-reason" name="reason" maxlength="2000" rows="3" ${action==='request_changes'?'required':''}></textarea></div><div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">${labels[action]}</button></div></form>`);}
async function mediaPage(renderId,append=false){if(!state.workspace){$('#main').innerHTML=title('Biblioteca','Imagens privadas, organizadas por marca.')+brandRequired();return;}const r=await api(workspacePath('/media?limit=24'+(append&&state.mediaCursor?'&cursor='+encodeURIComponent(state.mediaCursor):'')));if(state.renderId!==renderId)return;state.media=append?[...state.media,...r.data]:r.data;state.mediaCursor=r.meta?.nextCursor;$('#main').innerHTML=title('Sua biblioteca criativa.','Imagens privadas da marca '+state.workspace.name+'.','','BIBLIOTECA')+(canWrite()?`<form id="upload-form" class="upload-box"><label for="media-file">Adicionar imagem à marca</label><p>JPEG, PNG ou WebP estática. Até 5 MiB, 25 megapixels e 10.000 px por dimensão. Os pixels são regravados no servidor.</p><div class="actions"><input id="media-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" required><button class="btn primary" type="submit">${icon('plus')}Enviar imagem</button></div><div class="form-error section-gap" role="alert"></div></form>`:'')+(state.media.length?`<div class="media-grid">${state.media.map(m=>`<article class="media-card"><img src="${attr(mediaUrl(m))}" alt="${attr(m.originalName)}" loading="lazy"><div class="media-info"><strong title="${attr(m.originalName)}">${esc(m.originalName)}</strong><small>${esc(m.width)} × ${esc(m.height)} · ${esc(bytes(m.sizeBytes))}</small><div class="actions"><a class="btn small" href="${attr(mediaUrl(m))}" download>Baixar</a>${canWrite()?`<button class="btn small danger" data-media-delete="${attr(m.id)}">Excluir</button>`:''}</div></div></article>`).join('')}</div>`:empty('Toda boa ideia tem referências.','Adicione imagens à biblioteca desta marca para usá-las no editor.','','media'))+(state.mediaCursor?'<div class="pagination"><button class="btn" data-action="media-more">Carregar mais imagens</button></div>':'')+'<div class="notice">Imagens usadas em conteúdos ou no histórico de versões não podem ser excluídas. O download exige sessão e acesso à marca.</div>';}
async function clientApprovalsPage(renderId){if(!state.workspace){$('#main').innerHTML=title('Aprovações','Revise a arte, o texto, as redes e a data com o cliente.')+brandRequired();return;}const context=state.tenant.id+':'+state.workspace.id;await window.ClientApprovals.render({root:$('#main'),api,basePath:workspacePath(''),workspace:state.workspace,canWrite:canWrite(),renderId,isCurrent:id=>state.renderId===id&&context===state.tenant?.id+':'+state.workspace?.id,onError:showError,onToast:toast,onReauthenticate:reauthDialog});}
async function clientResultsPage(renderId){if(!state.workspace){$('#main').innerHTML=title('Dashboard do cliente','Resultados por marca e links de visualização.')+brandRequired();return;}const context=state.tenant.id+':'+state.workspace.id;await window.SocialResults.render({root:$('#main'),api,basePath:workspacePath(''),workspace:state.workspace,canManage:canManage(),renderId,isCurrent:id=>state.renderId===id&&context===state.tenant?.id+':'+state.workspace?.id,onError:showError,onToast:toast,onReauthenticate:reauthDialog});}
async function reportsPage(renderId){if(!state.workspace){$('#main').innerHTML=title('Dashboard','Estratégia e análise por marca.')+brandRequired();return;}const context=state.tenant.id+':'+state.workspace.id;await window.SocialStrategy.render({root:$('#main'),api,basePath:workspacePath(''),workspace:state.workspace,canWrite:canWrite(),canExport:canManage(),renderId,isCurrent:id=>state.renderId===id&&context===state.tenant?.id+':'+state.workspace?.id,onError:showError,onToast:toast,onReauthenticate:reauthDialog});}
async function brandsPage(renderId){const results=await Promise.all(state.workspaces.map(async w=>({workspace:w,channels:w.archivedAt?[]:(await api(tenantPath(`/workspaces/${safePath(w.id)}/channels?limit=100&archived=all`))).data})));if(state.renderId!==renderId)return;state.brandChannels=Object.fromEntries(results.map(r=>[r.workspace.id,r.channels]));$('#main').innerHTML=title('Marcas com espaço próprio.','Organize os clientes e os canais de planejamento.',canManage()?'<button class="btn primary" data-action="brand-new">'+icon('plus')+'Nova marca</button>':'','MARCAS E CANAIS')+(results.length?`<div class="grid-equal">${results.map(({workspace:w,channels})=>`<section class="panel"><div class="panel-head"><div><h2>${esc(w.name)}</h2><p>${w.archivedAt?'Marca arquivada':'Marca ativa'} · revisão ${w.version}</p></div>${canManage()?`<button class="btn small" data-brand-edit="${attr(w.id)}">Editar</button>`:''}</div><div class="panel-body"><div class="stack">${channels.map(c=>`<div class="row"><div class="actions"><span class="platform">${esc((platformLabels[c.platform]||c.platform).slice(0,2))}</span><span><strong class="inline-value">${esc(c.label)}</strong><small class="help">${esc(platformLabels[c.platform]||c.platform)} · ${c.archivedAt?'arquivado':'desconectado'}</small></span></div>${canManage()?`<button class="btn small" data-channel-edit="${attr(c.id)}" data-channel-workspace="${attr(w.id)}">Editar</button>`:''}</div>`).join('') || '<p class="help">Nenhum alvo editorial ativo.</p>'}</div>${canManage()&&!w.archivedAt?`<button class="btn small section-gap" data-channel-new="${attr(w.id)}">${icon('plus')}Adicionar alvo editorial</button>`:''}${canManage()?`<div class="rule"></div><button class="btn small ${w.archivedAt?'':'danger'}" data-brand-archive="${attr(w.id)}">${w.archivedAt?'Restaurar marca':'Arquivar marca'}</button>`:''}</div></section>`).join('')}</div>`:brandRequired())+(state.workspaceCursor?'<div class="pagination"><button class="btn" data-action="brands-more">Carregar mais marcas</button></div>':'')+'<div class="notice">Alvos editoriais organizam seu planejamento. Não são conexões OAuth e não têm acesso às contas das redes sociais.</div>';}
function brandDialog(wid){const w=state.workspaces.find(w=>w.id===wid);openDialog(`<h2 id="dialog-title">${w?'Editar marca':'Um novo espaço criativo.'}</h2><p>${w?'Atualize o nome e a cor de referência desta marca.':'Crie uma marca vazia. Os conteúdos e imagens pertencerão somente a ela.'}</p><form id="brand-form" data-brand-id="${attr(w?.id||'')}"><div class="field"><label for="brand-name">Nome da marca</label><input id="brand-name" name="name" required maxlength="120" value="${attr(w?.name||'')}"></div><div class="field"><label for="brand-color">Cor de referência</label><input id="brand-color" name="color" type="color" value="${attr(w?.color||'#7561cd')}"></div>${!w?'<div class="notice">Nenhum dado de exemplo será criado. Você pode adicionar alvos editoriais depois.</div>':''}<div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">${w?'Salvar alterações':'Criar marca'}</button></div></form>`);}
function channelDialog(wid,cid){const channel=(state.brandChannels?.[wid]||[]).find(c=>c.id===cid);openDialog(`<h2 id="dialog-title">${channel?'Editar alvo editorial':'Adicionar alvo editorial'}</h2><p>Organize o canal no planejamento. Nenhuma conexão com a rede social será criada.</p><form id="channel-form" data-workspace-id="${attr(wid)}" data-channel-id="${attr(channel?.id||'')}"><div class="field"><label for="channel-platform">Plataforma</label><select id="channel-platform" name="platform" ${channel?'disabled':''}>${Object.entries(platformLabels).map(([key,label])=>`<option value="${key}" ${channel?.platform===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="channel-label">Nome de referência</label><input id="channel-label" name="label" required maxlength="120" value="${attr(channel?.label||'')}" placeholder="Perfil da marca"></div>${channel?`<label class="check"><input name="archived" type="checkbox" ${channel.archivedAt?'checked':''}>Arquivar este alvo editorial</label>`:''}<div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">Salvar alvo editorial</button></div></form>`);}
async function teamPage(renderId,append=false){if(!canManage())throw Object.assign(new Error('Somente proprietários e administradores podem gerenciar a equipe.'),{status:403});const [members,invitations]=await Promise.all([append&&!state.memberCursor?Promise.resolve({data:[],meta:{nextCursor:null}}):api(tenantPath('/members?limit=50'+(append&&state.memberCursor?'&cursor='+encodeURIComponent(state.memberCursor):''))),append&&!state.invitationCursor?Promise.resolve({data:[],meta:{nextCursor:null}}):api(tenantPath('/invitations?limit=50'+(append&&state.invitationCursor?'&cursor='+encodeURIComponent(state.invitationCursor):'')))]);if(state.renderId!==renderId)return;state.members=append&&state.memberCursor?[...state.members,...members.data]:append?state.members:members.data;state.invitations=append&&state.invitationCursor?[...state.invitations,...invitations.data]:append?state.invitations:invitations.data;state.memberCursor=members.meta?.nextCursor;state.invitationCursor=invitations.meta?.nextCursor;$('#main').innerHTML=title('As pessoas fazem o espaço.','Papéis e marcas concedidas são verificados a cada solicitação.','<button class="btn primary" data-action="invite-new">'+icon('plus')+'Convidar pessoa</button>','EQUIPE E ACESSO')+`<section class="panel"><div class="panel-head"><h2>Membros ativos</h2><span class="pill">${state.members.length} carregado(s)</span></div><div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Papel</th><th>Marcas</th><th>Ações</th></tr></thead><tbody>${state.members.map(m=>`<tr><td><strong>${esc(m.displayName)}</strong><small>${esc(m.email)}</small></td><td>${esc(roles[m.role])}${m.userId===state.session.user.id?'<small>Você</small>':''}</td><td>${m.scope==='organization'?'Toda a organização':esc(m.workspaceIds.map(id=>state.workspaces.find(w=>w.id===id)?.name||'Marca indisponível').join(', ')||'Sem acesso a marcas')}</td><td>${state.tenant.role==='owner'||!['owner','admin'].includes(m.role)?`<button class="btn small" data-member-edit="${attr(m.userId)}">Gerenciar</button>`:'<small>Gerenciado pelo proprietário</small>'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Convites</h2><p>Convites válidos ainda não aceitos consomem um assento.</p></div></div>${state.invitations.length?`<div class="table-wrap"><table><thead><tr><th>Email</th><th>Papel</th><th>Estado</th><th>Ações</th></tr></thead><tbody>${state.invitations.map(i=>{const active=!i.acceptedAt&&!i.revokedAt;return `<tr><td>${esc(i.email)}${hostedPilot()?`<small>Referência: ${esc(i.id)}</small>`:""}<small>Expira em ${esc(fmt(i.expiresAt,{timeStyle:'short'}))}</small></td><td>${esc(roles[i.role])}</td><td>${i.acceptedAt?'Aceito':i.revokedAt?'Revogado':Date.parse(i.expiresAt)<Date.now()?'Expirado':'Pendente'}</td><td>${active&&(state.tenant.role==='owner'||!['owner','admin'].includes(i.role))?`<div class="actions"><button class="btn small" data-invite-resend="${attr(i.id)}">${hostedPilot()?'Invalidar link anterior':'Novo link local'}</button><button class="btn small danger" data-invite-revoke="${attr(i.id)}">Revogar</button></div>`:'—'}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Todo mundo começa com um convite.','Convide uma pessoa e escolha as marcas que ela poderá acessar.','','team')}</section>${state.memberCursor||state.invitationCursor?'<div class="pagination"><button class="btn" data-action="team-more">Carregar mais membros e convites</button></div>':''}${emailNotice()}`;}
function scopeFields(member){const role=member?.role || 'editor';return `<div class="field"><label for="member-role">Papel</label><select id="member-role" name="role">${Object.entries(roles).filter(([key])=>state.tenant.role==='owner'||!['owner','admin'].includes(key)).map(([key,label])=>`<option value="${key}" ${key===role?'selected':''}>${label}</option>`).join('')}</select><small class="help">Editor cria; revisor aprova; leitor apenas consulta. Proprietário e administrador têm acesso organizacional.</small></div><fieldset id="grants-fieldset" ${['owner','admin'].includes(role)?'hidden':''}><legend>Marcas permitidas</legend><div class="scope-options">${state.workspaces.filter(w=>!w.archivedAt).map(w=>`<label class="check"><input type="checkbox" name="workspaceIds" value="${attr(w.id)}" ${member?.workspaceIds?.includes(w.id)?'checked':''}>${esc(w.name)}</label>`).join('')||'<p class="help">Crie uma marca antes de convidar pessoas com escopo limitado.</p>'}</div><small class="help">Nenhuma marca selecionada significa nenhum acesso às marcas.</small></fieldset>`;}
function invitationDialog(){openDialog(`<h2 id="dialog-title">Convide alguém para criar junto.</h2><p>Escolha o papel e o acesso. ${hostedPilot()?'O responsável emitirá um link privado para a pessoa verificada.':'O link ficará no terminal do operador, sem envio externo.'}</p><form id="invite-form"><div class="field"><label for="invite-email">Email da pessoa</label><input id="invite-email" name="email" type="email" required maxlength="254"></div>${scopeFields()}<div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">${hostedPilot()?'Registrar convite':'Criar convite local'}</button></div></form>`);}
function memberDialog(uid){const member=state.members.find(m=>m.userId===uid);if(!member)return;openDialog(`<h2 id="dialog-title">Gerenciar acesso</h2><p>${esc(member.displayName)} · ${esc(member.email)}</p><form id="member-form" data-user-id="${attr(uid)}">${scopeFields(member)}<div class="notice">As mudanças passam a valer na próxima solicitação. Deve existir pelo menos um proprietário ativo.</div><div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn danger" data-member-remove="${attr(uid)}">Remover acesso</button><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">Salvar acesso</button></div></form>`);}
async function plansPage(renderId){const [plans,entitlements]=await Promise.all([api('/plans'),api(tenantPath('/entitlements'))]);if(state.renderId!==renderId)return;state.plans=plans.data;const e=entitlements.data;const labels={workspaces:'Marcas ativas',members:'Membros e convites válidos',posts:'Conteúdos não arquivados',mediaBytes:'Imagens normalizadas'};$('#main').innerHTML=title('Um espaço com limites claros.','Consumo real e capacidade do seu acesso.','','PLANO E USO')+`<div class="grid-two"><section class="panel"><div class="panel-head"><div><h2>${esc(e.plan.label)}</h2><p>${e.source==='manual_trial'?'Concessão manual de avaliação':'Origem: '+esc(e.source)} · versão ${esc(e.plan.version)}</p></div><span class="tag ${e.accessMode==='read_only'?'amber':'green'}">${e.accessMode==='read_only'?'Somente leitura':'Acesso de avaliação'}</span></div><div class="panel-body"><div class="usage-list">${e.usage?Object.entries(labels).map(([key,label])=>`<div><div class="usage-label"><span>${label}</span><strong>${key==='mediaBytes'?bytes(e.usage[key]):esc(e.usage[key])} / ${key==='mediaBytes'?bytes(e.limits[key]):esc(e.limits[key])}</strong></div><div class="meter ${(e.overLimit||[]).includes(key)?'danger':''}"><span data-progress="${Math.round(e.usage[key]/Math.max(1,e.limits[key])*100)}"></span></div></div>`).join(''):'<p class="help">Consumo total disponível apenas para proprietários e administradores.</p>'}</div><p class="help section-gap">${e.endsAt?'Acesso vigente até '+esc(fmt(e.endsAt,{timeStyle:'short'}))+'.':'Sem término informado pelo servidor.'} Reduzir limites não apaga dados existentes.</p></div></section><section class="panel"><div class="panel-head"><h2>Cobrança desativada</h2>${icon('shield')}</div><div class="panel-body"><h3>Preços a definir.</h3><p class="help">Este piloto não processa pagamentos, não cria assinaturas e não abre checkout. O plano exibido é uma concessão técnica, não um pagamento confirmado.</p><div class="notice">A escolha de preços e condições comerciais faz parte da preparação para lançamento. Nenhum cartão é solicitado.</div>${state.tenant.role==='owner'?'<button class="btn" type="button" disabled aria-describedby="billing-disabled">Checkout indisponível</button><p id="billing-disabled" class="help">Requer ativação e autorização do provedor de cobrança.</p>':''}</div></section></div><section class="section-gap"><div class="section-title"><div class="eyebrow">CATÁLOGO DO SERVIDOR</div><h2>Presets para avaliar o produto.</h2></div>${planCards(plans.data)}</section>`;applyProgress();}
async function settingsPage(renderId){if(state.renderId!==renderId)return;const t=state.tenant;$('#main').innerHTML=title('Seu espaço, bem cuidado.','Ajuste a organização e proteja seu acesso.','','CONFIGURAÇÕES')+`<div class="settings-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Organização</h2></div><div class="panel-body">${canManage()?`<form id="settings-form"><div class="field"><label for="settings-name">Nome da organização</label><input id="settings-name" name="name" value="${attr(t.name)}" required maxlength="100"></div><div class="field"><label for="settings-timezone">Fuso horário IANA</label><input id="settings-timezone" name="timezone" value="${attr(t.timezone)}" required maxlength="100"></div>${t.role==='owner'?`<label class="check"><input id="independent-policy" name="requireIndependentApproval" type="checkbox" ${t.requireIndependentApproval?'checked':''}>Exigir aprovação por outra pessoa</label><div class="field"><label for="policy-reason">Motivo da mudança de política</label><input id="policy-reason" name="reason" minlength="8" maxlength="500" placeholder="Obrigatório somente se mudar a regra"></div>`:`<div class="notice">Revisão independente ${t.requireIndependentApproval?'ativada':'desativada'}. Somente o proprietário pode alterar essa regra.</div>`}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Salvar configurações</button></form>`:`<p><strong>${esc(t.name)}</strong></p><p class="help">Fuso: ${esc(t.timezone)}<br>Revisão independente: ${t.requireIndependentApproval?'ativada':'desativada'}<br>Seu papel: ${esc(roles[t.role])}</p>`}</div></section><section class="panel"><div class="panel-head"><h2>Mais de uma organização</h2></div><div class="panel-body"><p class="help">Crie outro espaço separado ou alterne entre suas organizações no menu. O piloto aplica um limite de organizações por conta.</p><button class="btn" data-action="tenant-new">${icon('plus')}Criar outra organização</button></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Sua conta</h2>${icon('shield')}</div><div class="panel-body"><p class="inline-value"><strong>${esc(state.session.user.displayName)}</strong><br>${esc(state.session.user.email)}</p><div class="rule"></div><form id="password-form"><div class="field"><label for="current-password">Senha atual</label><input id="current-password" name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></div><div class="field"><label for="new-password">Nova senha</label><input id="new-password" name="password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"><small class="help">De 15 a 128 caracteres. Todas as sessões serão encerradas.</small></div><div class="form-error" role="alert"></div><button class="btn" type="submit">Alterar senha</button></form><div class="rule"></div><div class="actions"><button class="btn danger" data-action="logout-all">Encerrar todas as sessões</button><button class="btn" data-action="reauthenticate">Confirmar identidade</button></div></div></section><div class="notice">Este é um piloto controlado do AgendePost. Email externo e cobrança permanecem desativados. Publicação, coleta social e WhatsApp dependem de contas autorizadas, configuração do operador e servidor ativo.</div></div></div>`;}
async function adminPage(renderId,append=false){if(!isPlatformAdmin())throw Object.assign(new Error('Esta área exige a função de administrador da plataforma.'),{status:403});const [tenants,health]=await Promise.all([api('/admin/tenants?limit=100'+(append&&state.adminCursor?'&cursor='+encodeURIComponent(state.adminCursor):'')),api('/admin/health-summary')]);if(state.renderId!==renderId)return;state.adminTenants=append?[...state.adminTenants,...tenants.data]:tenants.data;state.adminCursor=tenants.meta?.nextCursor;const counters=Object.entries(health.data).filter(([,v])=>typeof v==='number');$('#main').innerHTML=title('Operação da plataforma.','Metadados operacionais, sem acesso ao conteúdo editorial dos clientes.','<button class="btn" data-action="reauthenticate">Confirmar identidade</button>','ADMINISTRAÇÃO')+`<div class="audit-counts">${counters.map(([key,value])=>`<div class="metric"><div class="metric-label">${esc(key)}</div><strong>${esc(value)}</strong><small>Contador operacional</small></div>`).join('')}</div><section class="panel section-gap"><div class="panel-head"><h2>Organizações</h2></div><div class="table-wrap"><table><thead><tr><th>Organização</th><th>Estado</th><th>Contagens</th><th>Concessão</th><th>Ação</th></tr></thead><tbody>${state.adminTenants.map(t=>`<tr><td>${esc(t.name)}<small>${esc(t.id)}</small></td><td>${esc(t.status)}</td><td>${esc(t.memberCount)} membros<br>${esc(t.workspaceCount)} marcas<br>${esc(t.postCount)} conteúdos</td><td>${esc(t.entitlement?.planId||'Sem plano')}<small>${esc(t.entitlement?.source||'')}<br>${esc(fmt(t.entitlement?.endsAt))}</small></td><td><button class="btn small" data-admin-grant="${attr(t.id)}">Conceder avaliação</button></td></tr>`).join('')}</tbody></table></div></section>${state.adminCursor?'<div class="pagination"><button class="btn" data-action="admin-more">Carregar mais organizações</button></div>':''}<div class="notice">Concessões são manuais e auditadas. Não representam receita, pagamento ou assinatura. Este papel não permite ler conteúdos privados de outras organizações.</div>`;}
function grantDialog(tid){const t=state.adminTenants.find(t=>t.id===tid);openDialog(`<h2 id="dialog-title">Conceder avaliação manual</h2><p>Organização: ${esc(t.name)}. Exige confirmação recente da identidade e motivo auditado.</p><form id="grant-form" data-tenant-id="${attr(tid)}"><div class="field"><label for="grant-plan">Preset técnico</label><select id="grant-plan" name="planId">${state.plans.map(p=>`<option value="${attr(p.id)}" data-version="${p.version}">${esc(p.label)} · v${p.version}</option>`).join('')}</select></div><div class="field"><label for="grant-end">Fim da avaliação (UTC)</label><input id="grant-end" name="endsAt" type="datetime-local" required><small class="help">Até 90 dias. O horário será tratado explicitamente como UTC.</small></div><div class="field"><label for="grant-reason">Motivo</label><textarea id="grant-reason" name="reason" required minlength="8" maxlength="500"></textarea></div><div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">Conceder avaliação</button></div></form>`);}
async function routeApp(){captureLinkToken();const renderId=++state.renderId;publishing.reset();window.SocialStrategy?.cleanup();window.SocialResults?.cleanup();window.ClientApprovals?.cleanup?.();const route=routeName();closeDialog();state.currentRoute=route;document.title='AgendePost · '+(route.startsWith('/app')?'seu espaço editorial':'planejamento em equipe');try{if(!state.session)await refreshSession(renderId);if(state.renderId!==renderId)return;if(['/','/features','/plans'].includes(route)){state.dirty=false;await landing(renderId);return;}const page=route.split('/')[1];if(['login','register','forgot','verify','reset','invitation'].includes(page)){authPage(page);return;}if(!route.startsWith('/app')){navigate('/',true);return;}await refreshSession(renderId);if(state.renderId!==renderId)return;if(!state.session.user){if(/^\/app\/connections\/[^/]+\/[^/]+$/.test(route))state.connectionReturnRoute=route;navigate('/login',true);return;}state.page=route.split('/')[2]||'dashboard';const connectionReturn=route.match(/^\/app\/connections\/([^/]+)\/([^/]+)$/);if(route.startsWith('/app/connections/')&&!connectionReturn)throw Object.assign(new Error('O retorno da conexão não identifica uma marca válida.'),{status:404});if(connectionReturn){const selected=state.tenants.find(t=>t.id===connectionReturn[1]);if(!selected)throw Object.assign(new Error('Você não tem acesso à organização desta autorização.'),{status:403});state.tenant=selected;state.workspace={id:connectionReturn[2]};}await loadTenantContext(renderId);if(state.renderId!==renderId)return;if(connectionReturn){if(state.workspace?.id!==connectionReturn[2])throw Object.assign(new Error('A marca desta autorização não está disponível para sua conta.'),{status:404});history.replaceState(null,'','#/app/connections');state.currentRoute='/app/connections';state.connectionReturnRoute=null;}if(!state.tenant && !(state.page==='admin'&&isPlatformAdmin())){onboarding();return;}shell();const pages={dashboard,posts:postsPage,calendar:calendarPage,publishing:publishing.queuePage,connections:publishing.connectionsPage,media:mediaPage,reports:reportsPage,results:clientResultsPage,approvals:clientApprovalsPage,brands:brandsPage,team:teamPage,plans:plansPage,settings:settingsPage,admin:adminPage};if(state.page==='editor')await editorPage(renderId,route.split('/')[3]||'new');else if(pages[state.page])await pages[state.page](renderId);else navigate('/app/dashboard',true);if(state.renderId===renderId)$('#main')?.setAttribute('tabindex','-1');}catch(e){if(state.renderId!==renderId)return;const main=$('#main');if(main)main.innerHTML=errorPage(e);else $('#app').innerHTML='<main id="main" class="main">'+errorPage(e)+'</main>';}}
function confirmDialog({heading,body,label='Confirmar',danger=false,onConfirm}){state.confirmAction=onConfirm;openDialog(`<h2 id="dialog-title">${esc(heading)}</h2><p>${esc(body)}</p><div class="form-error" role="alert"></div><div class="dialog-actions"><button class="btn" data-action="dialog-close">Cancelar</button><button class="btn ${danger?'danger':'primary'}" data-action="confirm-action">${esc(label)}</button></div>`);}
function reauthDialog(){openDialog('<h2 id="dialog-title">Confirme sua identidade</h2><p>Algumas mudanças exigem uma confirmação recente de senha. Depois, repita a ação desejada.</p><form id="reauth-form"><div class="field"><label for="reauth-password">Sua senha</label><input id="reauth-password" name="password" type="password" autocomplete="current-password" required minlength="15" maxlength="128"></div><div class="form-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn" data-action="dialog-close">Cancelar</button><button class="btn primary" type="submit">Confirmar identidade</button></div></form>');}
async function doLogout(all=false){if(hasUnsaved()){confirmDialog({heading:'Sair sem salvar?',body:'Suas alterações ainda não salvas serão descartadas desta aba.',label:'Sair da conta',danger:true,onConfirm:async()=>{discardLocalChanges();await doLogout(all);}});return;}const r=await api(all?'/auth/logout-all':'/auth/logout',{method:'POST',body:{}});state.csrf=r.data.csrfToken || '';sessionClear();await refreshSession();toast(all?'Todas as sessões foram encerradas.':'Você saiu da conta.');navigate('/login',true);}
function scopeData(f){const role=String(f.get('role'));const workspaceIds=['owner','admin'].includes(role)?[]:f.getAll('workspaceIds');return {role,workspaceIds};}
async function formHandler(form){const formRenderId=state.renderId;const stillActive=()=>state.renderId===formRenderId&&form.isConnected;const id=form.id;if(publishing.handlesForm(id)){await publishing.handleForm(form);return;}if(id==='editor-form'){await savePost(form);return;}await submitForm(form,async f=>{
 if(id==='login-form'){await api('/auth/login',{method:'POST',body:{email:String(f.get('email')),password:String(f.get('password'))}});await refreshSession();toast('Você entrou no seu espaço.');navigate(state.tokenPurpose==='invitation'&&state.token?'/invitation':state.connectionReturnRoute||'/app/dashboard',true);}
 else if(id==='register-form'){await api('/auth/register',{method:'POST',body:{email:String(f.get('email')),displayName:String(f.get('displayName')).trim()}});authLayout('<span class="tag green">Solicitação registrada</span><h1 class="section-gap">O próximo passo é verificar.</h1><p>Se o endereço puder receber uma verificação, o link será disponibilizado na caixa de saída local do operador. Nenhum email externo foi enviado.</p>'+emailNotice()+'<a class="btn primary full" href="#/login">Voltar para entrar</a><p class="auth-footer"><a href="#/verify">Solicitar outro link</a></p>');}
 else if(id==='forgot-form'||id==='resend-form'){await api(id==='forgot-form'?'/auth/password/forgot':'/auth/email/resend',{method:'POST',body:{email:String(f.get('email'))}});$('.form-error',form).classList.add('notice','success');$('.form-error',form).textContent='Se a conta for elegível, o link ficará na caixa de saída local. Nenhum email externo foi enviado.';}
 else if(id==='token-form'){if(f.get('password')!==f.get('confirm'))throw new Error('As senhas precisam ser iguais.');const purpose=form.dataset.purpose;await api(purpose==='verify'?'/auth/email/verify':'/auth/password/reset',{method:'POST',body:{token:state.token,password:String(f.get('password'))}});state.token=null;state.tokenPurpose=null;sessionClear();await refreshSession();toast(purpose==='verify'?'Conta verificada. Agora entre com sua senha.':'Senha alterada. Entre novamente.');navigate('/login',true);}
 else if(id==='accept-invite-form'){const r=await api('/invitations/accept',{method:'POST',body:{token:state.token},idempotent:true});state.token=null;state.tokenPurpose=null;state.tenant=r.data;state.workspace=null;await refreshSession();toast('Convite aceito. Bem-vindo à equipe.');navigate('/app/dashboard',true);}
 else if(id==='tenant-form'){const r=await api('/tenants',{method:'POST',body:{name:String(f.get('name')).trim(),timezone:String(f.get('timezone')).trim()},idempotent:true});state.tenant=r.data;state.workspace=null;await refreshSession();toast('Organização criada, sem dados de exemplo.');navigate('/app/dashboard',true);}
 else if(id==='brand-form'){const wid=form.dataset.brandId;const body={name:String(f.get('name')).trim(),color:String(f.get('color'))};if(wid)body.expectedVersion=state.workspaces.find(w=>w.id===wid).version;const r=await api(tenantPath('/workspaces'+(wid?'/'+safePath(wid):'')),{method:wid?'PATCH':'POST',body,idempotent:true});if(!stillActive())return;state.workspace=r.data;closeDialog();toast(wid?'Marca atualizada.':'Marca criada.');await routeApp();}
 else if(id==='channel-form'){const wid=form.dataset.workspaceId,cid=form.dataset.channelId;const body={label:String(f.get('label')).trim()};if(cid){body.expectedVersion=state.brandChannels[wid].find(c=>c.id===cid).version;body.archived=f.has('archived');}else body.platform=String(f.get('platform'));await api(tenantPath(`/workspaces/${safePath(wid)}/channels${cid?'/'+safePath(cid):''}`),{method:cid?'PATCH':'POST',body,idempotent:true});if(!stillActive())return;closeDialog();toast('Alvo editorial salvo. Continua desconectado.');await routeApp();}
 else if(id==='transition-form'){const action=form.dataset.transitionAction;const body={action,expectedRevision:state.revision};const reason=String(f.get('reason')||'').trim();if(reason)body.reason=reason;if(action==='plan'){body.scheduledAt=String(f.get('date'))+':00'+String(f.get('offset'));body.scheduledTimezone=String(f.get('scheduledTimezone')).trim();}await api(state.editorBasePath+'/transitions',{method:'POST',body,idempotent:true});if(!stillActive())return;closeDialog();toast(action==='plan'?'Data planejada. Nenhuma publicação foi feita.':'Status editorial atualizado.');await routeApp();}
 else if(id==='comment-form'){await api(state.editorBasePath+'/comments',{method:'POST',body:{body:String(f.get('body')).trim()},idempotent:true});if(!stillActive())return;form.reset();toast('Comentário adicionado.');await loadComments();}
 else if(id==='upload-form'){const file=f.get('file');if(!file?.size)throw new Error('Escolha uma imagem para enviar.');if(file.size>5*1024*1024)throw new Error('O arquivo deve ter no máximo 5 MiB.');const body=new FormData();body.append('file',file);await api(workspacePath('/media'),{method:'POST',body,idempotent:true});if(!stillActive())return;toast('Imagem adicionada à marca.');await mediaPage(state.renderId);}
 else if(id==='invite-form'){const data=scopeData(f);if(!['owner','admin'].includes(data.role)&&!data.workspaceIds.length)throw new Error('Selecione pelo menos uma marca para este convite.');await api(tenantPath('/invitations'),{method:'POST',body:{email:String(f.get('email')),...data},idempotent:true});if(!stillActive())return;closeDialog();toast(hostedPilot()?'Convite registrado. Solicite ao operador a emissão do link privado.':'Convite criado no outbox local. Nenhum email enviado.');await teamPage(state.renderId);}
 else if(id==='member-form'){const uid=form.dataset.userId;const member=state.members.find(m=>m.userId===uid);await api(tenantPath('/members/'+safePath(uid)),{method:'PATCH',body:{...scopeData(f),expectedVersion:member.version},idempotent:true});if(!stillActive())return;closeDialog();toast('Permissões atualizadas.');await routeApp();}
 else if(id==='settings-form'){const body={name:String(f.get('name')).trim(),timezone:String(f.get('timezone')).trim(),expectedVersion:state.tenant.version};if(state.tenant.role==='owner' && f.has('requireIndependentApproval')!==state.tenant.requireIndependentApproval){body.requireIndependentApproval=f.has('requireIndependentApproval');body.reason=String(f.get('reason')).trim();if(body.reason.length<8)throw new Error('Explique a mudança da política em pelo menos 8 caracteres.');}await api(tenantPath(),{method:'PATCH',body});if(!stillActive())return;toast('Configurações atualizadas.');await routeApp();}
 else if(id==='password-form'){await api('/auth/password/change',{method:'POST',body:{currentPassword:String(f.get('currentPassword')),password:String(f.get('password'))}});sessionClear();await refreshSession();toast('Senha alterada. Entre novamente.');navigate('/login',true);}
 else if(id==='reauth-form'){await api('/auth/reauthenticate',{method:'POST',body:{password:String(f.get('password'))}});if(!stillActive())return;closeDialog();toast('Identidade confirmada. Repita a ação desejada.');}
 else if(id==='grant-form'){const plan=state.plans.find(p=>p.id===f.get('planId'));if(!plan)throw new Error('Selecione um preset do catálogo.');await api('/admin/tenants/'+safePath(form.dataset.tenantId)+'/entitlement-grants',{method:'POST',body:{planId:plan.id,planVersion:plan.version,endsAt:String(f.get('endsAt'))+':00Z',reason:String(f.get('reason')).trim()},idempotent:true});if(!stillActive())return;closeDialog();toast('Avaliação manual concedida e auditada.');await adminPage(state.renderId);}
 });}
async function clickHandler(event){const publicationAction=event.target.closest('[data-publishing-action]');if(publicationAction){event.preventDefault();if(!publicationAction.disabled)await publishing.handleClick(publicationAction);return;}const link=event.target.closest('a[href^="#/"]');if(link&&hasUnsaved()&&link.getAttribute('href')!==location.hash){event.preventDefault();const target=link.getAttribute('href').slice(1);confirmDialog({heading:'Você tem alterações não salvas.',body:'Sair desta página descarta as alterações locais. Salve primeiro para preservá-las.',label:'Sair sem salvar',danger:true,onConfirm:async()=>{discardLocalChanges();closeDialog();navigate(target);}});return;}const el=event.target.closest('[data-action],[data-transition],[data-media-select],[data-media-delete],[data-brand-edit],[data-brand-archive],[data-channel-new],[data-channel-edit],[data-member-edit],[data-member-remove],[data-invite-resend],[data-invite-revoke],[data-admin-grant]');if(!el||el.disabled)return;event.preventDefault();const action=el.dataset.action;try{
 if(el.dataset.transition){transitionDialog(el.dataset.transition);return;}
 if(el.dataset.mediaSelect){const id=el.dataset.mediaSelect;if(state.selectedMedia.has(id))state.selectedMedia.delete(id);else if(state.selectedMedia.size>=10){toast('Selecione no máximo 10 imagens.');return;}else state.selectedMedia.add(id);$('#editor-media').innerHTML=editorMediaMarkup();markDirty();return;}
 if(el.dataset.mediaDelete){const id=el.dataset.mediaDelete;confirmDialog({heading:'Excluir imagem?',body:'A exclusão só é permitida se a imagem não estiver vinculada a um conteúdo ou a seu histórico.',label:'Excluir imagem',danger:true,onConfirm:async()=>{await api(workspacePath('/media/'+safePath(id)),{method:'DELETE',body:{}});closeDialog();toast('Imagem excluída.');await mediaPage(state.renderId);}});return;}
 if(el.dataset.brandEdit){brandDialog(el.dataset.brandEdit);return;}
 if(el.dataset.brandArchive){const w=state.workspaces.find(w=>w.id===el.dataset.brandArchive);confirmDialog({heading:w.archivedAt?'Restaurar marca?':'Arquivar marca?',body:w.archivedAt?'A marca volta ao planejamento ativo, sujeita aos limites do plano.':'A marca ficará fora do seletor ativo. Seus dados serão preservados e ela poderá ser restaurada.',label:w.archivedAt?'Restaurar':'Arquivar',onConfirm:async()=>{await api(tenantPath('/workspaces/'+safePath(w.id)),{method:'PATCH',body:{archived:!w.archivedAt,expectedVersion:w.version},idempotent:true});closeDialog();toast('Marca atualizada.');await routeApp();}});return;}
 if(el.dataset.channelNew){channelDialog(el.dataset.channelNew);return;}if(el.dataset.channelEdit){channelDialog(el.dataset.channelWorkspace,el.dataset.channelEdit);return;}
 if(el.dataset.memberEdit){memberDialog(el.dataset.memberEdit);return;}
 if(el.dataset.memberRemove){const m=state.members.find(m=>m.userId===el.dataset.memberRemove);confirmDialog({heading:'Remover acesso à organização?',body:`${m.displayName} (${m.email}) perderá o acesso a esta organização e às suas marcas na próxima solicitação.`,label:'Remover acesso',danger:true,onConfirm:async()=>{await api(tenantPath('/members/'+safePath(m.userId)),{method:'DELETE',body:{expectedVersion:m.version}});closeDialog();toast('Acesso removido.');await routeApp();}});return;}
 if(el.dataset.inviteResend){el.disabled=true;await api(tenantPath('/invitations/'+safePath(el.dataset.inviteResend)+'/resend'),{method:'POST',body:{},idempotent:true});toast(hostedPilot()?'Link anterior invalidado. Peça ao operador para emitir o novo link.':'Novo link gerado localmente. O anterior foi invalidado.');await teamPage(state.renderId);return;}
 if(el.dataset.inviteRevoke){const id=el.dataset.inviteRevoke;confirmDialog({heading:'Revogar convite?',body:'O link deste convite deixará de conceder acesso.',label:'Revogar convite',danger:true,onConfirm:async()=>{await api(tenantPath('/invitations/'+safePath(id)+'/revoke'),{method:'POST',body:{},idempotent:true});closeDialog();toast('Convite revogado.');await teamPage(state.renderId);}});return;}
 if(el.dataset.adminGrant){if(!state.plans.length)state.plans=(await api('/plans')).data;grantDialog(el.dataset.adminGrant);return;}
 if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('show');}
 else if(action==='menu-close'){$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('show');}
 else if(action==='dialog-close'){closeDialog();state.confirmAction=null;}
 else if(action==='confirm-action'){el.disabled=true;try{await state.confirmAction?.();}catch(e){showError(e,$('.form-error',$('#dialog')));}finally{el.disabled=false;}}
 else if(action==='reload'){await routeApp();}
 else if(action==='logout')await doLogout();
 else if(action==='logout-all')confirmDialog({heading:'Encerrar todas as sessões?',body:'Você precisará entrar novamente em todos os navegadores, incluindo este.',label:'Encerrar sessões',onConfirm:async()=>{closeDialog();await doLogout(true);}});
 else if(action==='brand-new')brandDialog();
 else if(action==='tenant-new'){state.tenant=null;onboarding();}
 else if(action==='invite-new')invitationDialog();
 else if(action==='reauthenticate')reauthDialog();
 else if(action==='posts-more'){el.disabled=true;const loaded=await loadPosts(true);if(!loaded.ignored)$('#main').innerHTML=postsMarkup();}
 else if(action==='media-more'){el.disabled=true;await mediaPage(state.renderId,true);}
 else if(action==='calendar-more'){el.disabled=true;await calendarPage(state.renderId,true);}
 else if(action==='admin-more'){el.disabled=true;await adminPage(state.renderId,true);}
 else if(action==='team-more'){el.disabled=true;await teamPage(state.renderId,true);}
 else if(action==='brands-more'){el.disabled=true;const r=await api(tenantPath('/workspaces?limit=100&archived=all&cursor='+encodeURIComponent(state.workspaceCursor)));state.workspaces.push(...r.data);state.workspaceCursor=r.meta?.nextCursor;await brandsPage(state.renderId);}
 else if(action==='comments-more'){el.disabled=true;await loadComments(true);}
 else if(action==='revisions-more'){el.disabled=true;await loadRevisions(true);}
 else if(action==='editor-media-more'){el.disabled=true;const r=await api(workspacePath('/media?limit=100&cursor='+encodeURIComponent(state.mediaCursor)));state.media.push(...r.data);state.mediaCursor=r.meta?.nextCursor;$('#editor-media').innerHTML=editorMediaMarkup(canWrite());if(!state.mediaCursor)el.remove();}
 else if(['month-prev','month-next','month-now'].includes(action)){state.month=action==='month-now'?new Date(new Date().getFullYear(),new Date().getMonth(),1):new Date(state.month.getFullYear(),state.month.getMonth()+(action==='month-next'?1:-1),1);await calendarPage(state.renderId);}
 else if(action==='post-duplicate'){if(state.dirty){toast('Salve suas alterações antes de duplicar.');return;}el.disabled=true;const r=await api(state.editorBasePath+'/duplicate',{method:'POST',body:{},idempotent:true});toast('Cópia criada como novo rascunho, sem aprovação.');navigate('/app/editor/'+r.data.id);}
 else if(action==='post-reload')confirmDialog({heading:'Recarregar a versão atual?',body:'As mudanças não salvas deste formulário serão descartadas. Copie seu texto antes se quiser preservá-lo.',label:'Recarregar',danger:true,onConfirm:async()=>{state.dirty=false;closeDialog();await routeApp();}});
 else if(action==='export'){el.disabled=true;const r=await api(tenantPath('/export/editorial'));const blob=new Blob([JSON.stringify(r.data??r,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='exportacao-editorial.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportação editorial preparada.');}
 }catch(e){showError(e);if(e.code==='REAUTH_REQUIRED')reauthDialog();}finally{if(el.isConnected)el.disabled=false;}}
document.addEventListener('submit',event=>{if(event.target.matches('form')){event.preventDefault();formHandler(event.target).catch(showError);}});
document.addEventListener('click',event=>{clickHandler(event).catch(showError);});
document.addEventListener('input',event=>{if(event.target.closest('#editor-form')){markDirty();if(event.target.id==='post-caption')$('#caption-count').textContent=event.target.value.length;}if(event.target.id==='post-search'){state.filters.search=event.target.value;$('#post-list').innerHTML=postListBody();}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='tenant-select'||el.id==='brand-select'){const requested=el.value,destination=['reports','results','approvals','publishing','connections'].includes(state.page)?'/app/'+state.page:'/app/dashboard';if(requested===(el.id==='tenant-select'?state.tenant?.id:state.workspace?.id))return;if(hasUnsaved()){el.value=el.id==='tenant-select'?state.tenant.id:state.workspace.id;confirmDialog({heading:'Trocar de espaço sem salvar?',body:'Suas alterações locais ainda não foram salvas.',label:'Trocar sem salvar',danger:true,onConfirm:async()=>{discardLocalChanges();closeDialog();if(el.id==='tenant-select'){state.tenant=state.tenants.find(t=>t.id===requested);state.workspace=null;}else state.workspace=state.workspaces.find(w=>w.id===requested);navigate(destination,true);}});return;}if(el.id==='tenant-select'){state.tenant=state.tenants.find(t=>t.id===requested);state.workspace=null;}else state.workspace=state.workspaces.find(w=>w.id===requested);state.posts=[];state.media=[];state.post=null;state.filters={status:'',search:''};navigate(destination,true);}else if(el.id==='post-status'){state.filters.status=el.value;const loaded=await loadPosts();if(!loaded.ignored)$('#main').innerHTML=postsMarkup();}else if(el.id==='member-role')$('#grants-fieldset').hidden=['owner','admin'].includes(el.value);else if(el.closest('#editor-form'))markDirty();}catch(e){showError(e);}});
window.addEventListener('hashchange',()=>{if(hasUnsaved() && (state.currentRoute?.startsWith('/app/editor')||state.currentRoute==='/app/reports'||state.currentRoute==='/app/approvals') && routeName()!==state.currentRoute){const next=routeName();history.replaceState(null,'','#'+state.currentRoute);confirmDialog({heading:'Você tem alterações não salvas.',body:'Voltar ou mudar de página descarta o texto ainda não salvo.',label:'Sair sem salvar',danger:true,onConfirm:async()=>{discardLocalChanges();closeDialog();navigate(next);}});return;}routeApp();});
window.addEventListener('beforeunload',event=>{if(hasUnsaved()){event.preventDefault();event.returnValue='';}});
window.addEventListener('pageshow',event=>{if(event.persisted){sessionClear();state.session=null;routeApp();}});
routeApp();
})();
